// Synthetic charts, generated by code: the XML of chart parts the way Excel
// writes them, and workbooks that hold such parts in the drawing of a sheet
// or as a chart sheet.

import { ZipArchive } from '../src/zip';
import { parseXml } from '../src/xml';
import { parseChart } from '../src/formats/xlsx/chart';
import type { Chart } from '../src/model/sheet/chart';
import { buildXlsx, utf8, worksheetXml } from './fixtures';
import { THEME, drawingXml } from './sheet-drawing-fixtures';

const XML = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
const NS_REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
const NS_PKG_REL = 'http://schemas.openxmlformats.org/package/2006/relationships';
const NS_MAIN = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main';
export const NS_C = 'http://schemas.openxmlformats.org/drawingml/2006/chart';
export const NS_A = 'http://schemas.openxmlformats.org/drawingml/2006/main';

/** Theme colours as the style sheet keeps them: lt1, dk1, lt2, dk2, accent1..6, hlink, folHlink. */
export const OFFICE_THEME = ['FFFFFF', '000000', 'E7E6E6', '44546A', '4472C4', 'ED7D31', 'A5A5A5', 'FFC000', '5B9BD5', '70AD47', '0563C1', '954F72'];

const escape = (text: string) => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const points = (values: (number | string | null)[]) =>
  `<c:ptCount val="${values.length}"/>` + values.map((value, i) => (value === null ? '' : `<c:pt idx="${i}"><c:v>${escape(String(value))}</c:v></c:pt>`)).join('');

export const numRef = (formula: string, values: (number | string | null)[], formatCode = 'General') =>
  `<c:numRef><c:f>${escape(formula)}</c:f><c:numCache><c:formatCode>${escape(formatCode)}</c:formatCode>${points(values)}</c:numCache></c:numRef>`;

export const strRef = (formula: string, values: (string | null)[]) => `<c:strRef><c:f>${escape(formula)}</c:f><c:strCache>${points(values)}</c:strCache></c:strRef>`;

export const numLit = (values: (number | null)[]) => `<c:numLit><c:formatCode>General</c:formatCode>${points(values)}</c:numLit>`;

export const strLit = (values: (string | null)[]) => `<c:strLit>${points(values)}</c:strLit>`;

export const solid = (rgb: string) => `<a:solidFill><a:srgbClr val="${rgb}"/></a:solidFill>`;

export const spPr = (inner: string) => `<c:spPr>${inner}</c:spPr>`;

export interface SerSpec {
  idx?: number;
  order?: number;
  /** Inner XML of <c:tx> (a strRef, or <c:v>). */
  tx?: string;
  /** Inner XML of <c:cat> / <c:xVal>. */
  cat?: string;
  /** Inner XML of <c:val> / <c:yVal>. */
  val?: string;
  /** Elements placed after <c:tx>: spPr, marker, dPt, invertIfNegative, dLbls. */
  props?: string;
  /** Elements placed last (smooth). */
  tail?: string;
}

/** A series of any chart type but scatter. */
export const ser = (index: number, spec: SerSpec) =>
  `<c:ser><c:idx val="${spec.idx ?? index}"/><c:order val="${spec.order ?? index}"/>${spec.tx !== undefined ? `<c:tx>${spec.tx}</c:tx>` : ''}${spec.props ?? ''}` +
  `${spec.cat !== undefined ? `<c:cat>${spec.cat}</c:cat>` : ''}${spec.val !== undefined ? `<c:val>${spec.val}</c:val>` : ''}${spec.tail ?? ''}</c:ser>`;

/** A series of a scatter chart: `cat` are the x values. */
export const xySer = (index: number, spec: SerSpec) =>
  `<c:ser><c:idx val="${spec.idx ?? index}"/><c:order val="${spec.order ?? index}"/>${spec.tx !== undefined ? `<c:tx>${spec.tx}</c:tx>` : ''}${spec.props ?? ''}` +
  `${spec.cat !== undefined ? `<c:xVal>${spec.cat}</c:xVal>` : ''}${spec.val !== undefined ? `<c:yVal>${spec.val}</c:yVal>` : ''}${spec.tail ?? ''}</c:ser>`;

const AX = '<c:axId val="111"/><c:axId val="222"/>';

/** A chart type element: `head` are the elements before the series (barDir, grouping, varyColors), `tail` those after (gapWidth, overlap, marker). */
export const group = (name: string, head: string, series: string, tail = '', axes = true) => `<c:${name}>${head}${series}${tail}${axes ? AX : ''}</c:${name}>`;

export const catAx = (inner = '', name = 'catAx') =>
  `<c:${name}><c:axId val="111"/><c:scaling><c:orientation val="minMax"/></c:scaling><c:delete val="0"/><c:axPos val="b"/>${inner}<c:crossAx val="222"/></c:${name}>`;

/** `scaling` is the inner XML of <c:scaling>. */
export const valAx = (inner = '<c:majorGridlines/>', scaling = '<c:orientation val="minMax"/>') =>
  `<c:valAx><c:axId val="222"/><c:scaling>${scaling}</c:scaling><c:delete val="0"/><c:axPos val="l"/>${inner}<c:crossAx val="111"/></c:valAx>`;

/** The two value axes of a scatter chart. */
export const xyAxes = () =>
  '<c:valAx><c:axId val="111"/><c:scaling><c:orientation val="minMax"/></c:scaling><c:delete val="0"/><c:axPos val="b"/><c:crossAx val="222"/></c:valAx>' +
  '<c:valAx><c:axId val="222"/><c:scaling><c:orientation val="minMax"/></c:scaling><c:delete val="0"/><c:axPos val="l"/><c:majorGridlines/><c:crossAx val="111"/></c:valAx>';

export interface ChartSpec {
  /** Inner XML of <c:plotArea>: chart types and axes. */
  plot: string;
  /** Elements of <c:chart> before the plot area (title, autoTitleDeleted). */
  head?: string;
  /** Elements of <c:chart> after the plot area (legend, plotVisOnly, dispBlanksAs). */
  tail?: string;
  /** Elements of <c:chartSpace> before <c:chart> (date1904, roundedCorners, style). */
  before?: string;
  /** Elements of <c:chartSpace> after <c:chart> (spPr, txPr). */
  after?: string;
}

/** A complete chart part. */
export const chartXml = (spec: ChartSpec) =>
  `${XML}<c:chartSpace xmlns:c="${NS_C}" xmlns:a="${NS_A}" xmlns:r="${NS_REL}">${spec.before ?? ''}` +
  `<c:chart>${spec.head ?? ''}<c:plotArea><c:layout/>${spec.plot}</c:plotArea>${spec.tail ?? '<c:plotVisOnly val="1"/><c:dispBlanksAs val="gap"/>'}</c:chart>${spec.after ?? ''}</c:chartSpace>`;

export const title = (text: string, runProps = '') =>
  `<c:title><c:tx><c:rich><a:bodyPr/><a:lstStyle/><a:p><a:r><a:rPr lang="en-US"${runProps ? ` ${runProps}` : ''}/><a:t>${escape(text)}</a:t></a:r></a:p></c:rich></c:tx><c:overlay val="0"/></c:title>`;

export const legend = (position: string, inner = '') => `<c:legend><c:legendPos val="${position}"/>${inner}<c:overlay val="0"/></c:legend>`;

/** The model of a chart part given as XML; undefined for one that is not drawn. */
export function readChart(xml: string, theme: string[] = OFFICE_THEME): Chart | undefined {
  return parseChart(parseXml(xml).root, theme);
}

/** The frame of a chart in a drawing: names the chart part by relationship id. */
export const chartFrameOf = (rel: string, name = 'Chart 1') =>
  `<xdr:graphicFrame macro=""><xdr:nvGraphicFramePr><xdr:cNvPr id="2" name="${name}"/><xdr:cNvGraphicFramePr/></xdr:nvGraphicFramePr>` +
  '<xdr:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/></xdr:xfrm>' +
  `<a:graphic><a:graphicData uri="${NS_C}"><c:chart xmlns:c="${NS_C}" xmlns:r="${NS_REL}" r:id="${rel}"/></a:graphicData></a:graphic></xdr:graphicFrame>`;

export interface ChartBookSpec {
  /** Inner XML of the first worksheet ("Sayfa1") before the reference to its drawing. */
  sheet?: string;
  /** Further worksheets: name and inner XML. */
  sheets?: { name: string; xml: string }[];
  /** Inner XML of the drawing of the first sheet: anchors, with chartFrameOf('rIdC1'), chartFrameOf('rIdC2'), ... inside. */
  drawing?: string;
  /** The chart parts of that drawing: chart1.xml is "rIdC1", and so on. */
  charts?: (string | Uint8Array)[];
  /** A chart sheet ("Grafik1") placed after the worksheets, with this chart part. */
  chartSheet?: string | Uint8Array;
  styles?: string;
  workbookHead?: string;
  /** Relationship type of the chart parts; that of a chart by default. */
  relType?: string;
}

/**
 * A workbook whose first sheet has a drawing with charts, and, when asked
 * for, a chart sheet: sheet -> drawing -> chart parts, as Excel lays them out.
 */
export async function chartWorkbook(spec: ChartBookSpec): Promise<Uint8Array> {
  const worksheets = [{ name: 'Sayfa1', xml: worksheetXml((spec.sheet ?? '<sheetData/>') + (spec.drawing !== undefined ? '<drawing r:id="rIdD"/>' : '')) }].concat(
    (spec.sheets ?? []).map((sheet) => ({ name: sheet.name, xml: worksheetXml(sheet.xml) })),
  );
  const sheets: { name: string; xml: string; kind?: 'chartsheet' }[] = worksheets.slice();
  if (spec.chartSheet !== undefined) {
    sheets.push({
      name: 'Grafik1',
      kind: 'chartsheet',
      xml: `${XML}<chartsheet xmlns="${NS_MAIN}" xmlns:r="${NS_REL}"><sheetPr/><sheetViews><sheetView zoomScale="90" workbookViewId="0"/></sheetViews><drawing r:id="rId1"/></chartsheet>`,
    });
  }
  const zip = ZipArchive.read(await buildXlsx({ theme: THEME, sheets, styles: spec.styles, workbookHead: spec.workbookHead }));
  const relType = spec.relType ?? `${NS_REL}/chart`;
  const overrides: string[] = [];
  const charts = spec.charts ?? [];
  if (spec.drawing !== undefined) {
    zip.set('xl/worksheets/_rels/sheet1.xml.rels', utf8(`${XML}<Relationships xmlns="${NS_PKG_REL}"><Relationship Id="rIdD" Type="${NS_REL}/drawing" Target="../drawings/drawing1.xml"/></Relationships>`));
    zip.set('xl/drawings/drawing1.xml', utf8(drawingXml(spec.drawing)));
    overrides.push('<Override PartName="/xl/drawings/drawing1.xml" ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/>');
    const rels = charts.map((_chart, i) => `<Relationship Id="rIdC${i + 1}" Type="${relType}" Target="../charts/chart${i + 1}.xml"/>`).join('');
    zip.set('xl/drawings/_rels/drawing1.xml.rels', utf8(`${XML}<Relationships xmlns="${NS_PKG_REL}">${rels}</Relationships>`));
  }
  charts.forEach((chart, i) => {
    zip.set(`xl/charts/chart${i + 1}.xml`, typeof chart === 'string' ? utf8(chart) : chart);
    overrides.push(`<Override PartName="/xl/charts/chart${i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.drawingml.chart+xml"/>`);
  });
  if (spec.chartSheet !== undefined) {
    const index = sheets.length;
    const number = charts.length + 1;
    zip.set(
      `xl/chartsheets/_rels/sheet${index}.xml.rels`,
      utf8(`${XML}<Relationships xmlns="${NS_PKG_REL}"><Relationship Id="rId1" Type="${NS_REL}/drawing" Target="../drawings/drawing9.xml"/></Relationships>`),
    );
    // The drawing of a chart sheet: one frame at a fixed place.
    zip.set(
      'xl/drawings/drawing9.xml',
      utf8(drawingXml(`<xdr:absoluteAnchor><xdr:pos x="0" y="0"/><xdr:ext cx="9300000" cy="6070000"/>${chartFrameOf('rId1')}<xdr:clientData/></xdr:absoluteAnchor>`)),
    );
    zip.set(
      'xl/drawings/_rels/drawing9.xml.rels',
      utf8(`${XML}<Relationships xmlns="${NS_PKG_REL}"><Relationship Id="rId1" Type="${relType}" Target="../charts/chart${number}.xml"/></Relationships>`),
    );
    zip.set(`xl/charts/chart${number}.xml`, typeof spec.chartSheet === 'string' ? utf8(spec.chartSheet) : spec.chartSheet);
    overrides.push('<Override PartName="/xl/drawings/drawing9.xml" ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/>');
    overrides.push(`<Override PartName="/xl/charts/chart${number}.xml" ContentType="application/vnd.openxmlformats-officedocument.drawingml.chart+xml"/>`);
  }
  const types = new TextDecoder().decode(await zip.read('[Content_Types].xml'));
  zip.set('[Content_Types].xml', utf8(types.replace('</Types>', `${overrides.join('')}</Types>`)));
  return zip.write();
}

/** Rows of numbers and texts as the inner XML of <sheetData>: texts are inline strings. */
export function sheetData(rows: (number | string | null)[][], rowProps: Record<number, string> = {}): string {
  const letter = (col: number) => String.fromCharCode(65 + col);
  return (
    '<sheetData>' +
    rows
      .map(
        (row, r) =>
          `<row r="${r + 1}"${rowProps[r] ? ` ${rowProps[r]}` : ''}>` +
          row
            .map((value, c) =>
              value === null ? '' : typeof value === 'number' ? `<c r="${letter(c)}${r + 1}"><v>${value}</v></c>` : `<c r="${letter(c)}${r + 1}" t="inlineStr"><is><t>${escape(value)}</t></is></c>`,
            )
            .join('') +
          '</row>',
      )
      .join('') +
    '</sheetData>'
  );
}

/** A stand-in for measuring text: every character is half the font size wide. */
export const fakeMeasure = (text: string, font: { size: number }) => text.length * font.size * 0.5;
